using System;
using System.Globalization;
using System.IO;
using System.Text;
using System.Xml;
using System.Web.Script.Serialization;
using NavPro.Backend.Models;
using NavPro.Classes;

namespace NavPro.Backend.Services
{
    /// <summary>Writes a self-contained, portable HTML dashboard for saved Clash Detective results.</summary>
    internal static class ClashDashboardWriter
    {
        public static void WriteTabular(string path, ClashDashboardSnapshot snapshot)
        {
            var b = new StringBuilder("<!doctype html><meta charset=\"utf-8\"><title>Clash Report</title><style>body{font:14px Arial}table{border-collapse:collapse}th{background:#A500A4;color:white}td,th{border:1px solid #bbb;padding:6px}</style><h1>");
            b.Append(System.Net.WebUtility.HtmlEncode(snapshot.ProjectName)).Append("</h1><table><thead><tr><th>Test</th><th>Test type</th><th>Clash</th><th>Status</th><th>Items</th><th>Distance</th><th>X</th><th>Y</th><th>Z</th><th>Assigned to</th></tr></thead><tbody>");
            foreach (var r in snapshot.Results) b.Append("<tr><td>").Append(System.Net.WebUtility.HtmlEncode(r.TestName)).Append("</td><td>").Append(System.Net.WebUtility.HtmlEncode(r.TestType)).Append("</td><td>").Append(System.Net.WebUtility.HtmlEncode(r.ClashName)).Append("</td><td>").Append(System.Net.WebUtility.HtmlEncode(r.Status)).Append("</td><td>").Append(System.Net.WebUtility.HtmlEncode(r.ItemA + " / " + r.ItemB)).Append("</td><td>").Append(r.Distance.ToString("G", CultureInfo.InvariantCulture)).Append("</td><td>").Append(r.X.ToString("G", CultureInfo.InvariantCulture)).Append("</td><td>").Append(r.Y.ToString("G", CultureInfo.InvariantCulture)).Append("</td><td>").Append(r.Z.ToString("G", CultureInfo.InvariantCulture)).Append("</td><td>").Append(System.Net.WebUtility.HtmlEncode(r.AssignedTo)).Append("</td></tr>");
            b.Append("</tbody></table>"); File.WriteAllText(path, b.ToString(), new UTF8Encoding(false));
        }

        public static void WriteXml(string path, ClashDashboardSnapshot snapshot)
        {
            using (var writer = XmlWriter.Create(path, new XmlWriterSettings { Encoding = new UTF8Encoding(false), Indent = true }))
            {
                writer.WriteStartDocument(); writer.WriteStartElement("NavProClashReport"); writer.WriteAttributeString("project", snapshot.ProjectName ?? ""); writer.WriteAttributeString("exportedAt", snapshot.ExportedAt ?? ""); writer.WriteAttributeString("units", snapshot.DisplayUnits ?? "");
                writer.WriteStartElement("Tests"); foreach (var test in snapshot.Tests) { writer.WriteStartElement("Test"); writer.WriteAttributeString("name", test.Name ?? ""); writer.WriteAttributeString("type", test.Type ?? ""); writer.WriteAttributeString("status", test.Status ?? ""); writer.WriteAttributeString("tolerance", test.Tolerance.ToString("R", CultureInfo.InvariantCulture)); writer.WriteAttributeString("resultCount", test.ClashCount.ToString(CultureInfo.InvariantCulture)); writer.WriteEndElement(); } writer.WriteEndElement();
                writer.WriteStartElement("Results"); foreach (var r in snapshot.Results) { writer.WriteStartElement("Clash"); writer.WriteAttributeString("test", r.TestName ?? ""); writer.WriteAttributeString("name", r.ClashName ?? ""); writer.WriteAttributeString("status", r.Status ?? ""); writer.WriteAttributeString("assignedTo", r.AssignedTo ?? ""); writer.WriteAttributeString("approvedBy", r.ApprovedBy ?? ""); writer.WriteAttributeString("distance", r.Distance.ToString("R", CultureInfo.InvariantCulture)); writer.WriteAttributeString("x", r.X.ToString("R", CultureInfo.InvariantCulture)); writer.WriteAttributeString("y", r.Y.ToString("R", CultureInfo.InvariantCulture)); writer.WriteAttributeString("z", r.Z.ToString("R", CultureInfo.InvariantCulture)); writer.WriteElementString("ItemA", r.ItemA ?? ""); writer.WriteElementString("ItemB", r.ItemB ?? ""); writer.WriteEndElement(); } writer.WriteEndElement(); writer.WriteEndElement(); writer.WriteEndDocument();
            }
        }

        public static void Write(string path, ClashDashboardSnapshot snapshot)
        {
            var serializer = new JavaScriptSerializer { MaxJsonLength = int.MaxValue, RecursionLimit = 128 };
            string json = serializer.Serialize(snapshot).Replace("&", "\\u0026").Replace("<", "\\u003c").Replace(">", "\\u003e").Replace("\u2028", "\\u2028").Replace("\u2029", "\\u2029");
            string html = Template.Replace("</style></head>", "</style>" + DashboardStyleOverrides + "</head>").Replace("__DATA__", json).Replace("__UNITS__", System.Net.WebUtility.HtmlEncode(snapshot.DisplayUnits ?? "")).Replace("__EMAIL__", System.Net.WebUtility.HtmlEncode(NavProIdentity.ContactEmail)).Replace("__LOGO__", DashboardLogoDataUri());
            File.WriteAllText(path, html, new UTF8Encoding(false));
        }

        private static string DashboardLogoDataUri()
        {
            using (var stream = typeof(ClashDashboardWriter).Assembly.GetManifestResourceStream("NavPro.Assets.NavProDashboardLogo.png"))
            {
                if (stream == null) throw new InvalidOperationException("The embedded NavPro dashboard logo is missing.");
                using (var image = new MemoryStream())
                {
                    stream.CopyTo(image);
                    return "data:image/png;base64," + Convert.ToBase64String(image.ToArray());
                }
            }
        }

