</style></head><body><header class="topbar"><div class="topbar-brand"><img src="__LOGO__" alt=""><span>NavPro</span></div><span class="topbar-divider"></span><strong>Clash Dashboard</strong></header><div class="layout"><aside class="side"><button class="primary" onclick="document.getElementById('files').click()">＋ Add Files</button><input id="files" type="file" accept=".html,text/html" multiple hidden><button id="pickFolder">▣ Select Reports Folder</button><input id="folderPicker" type="file" webkitdirectory directory multiple hidden><div id="folderStatus" class="sub" aria-live="polite">Select a folder of saved NavPro HTML clash reports for automatic refresh.</div><button onclick="window.print()">▣ Print PDF</button><a class="contact-link no-print" href="mailto:__EMAIL__?subject=NavPro%20Clash%20Dashboard%20Support" aria-label="Contact NavPro support by email at __EMAIL__"><span>✉ Contact Info</span><small>__EMAIL__</small></a><section class="filter"><div class="filter-heading"><h3>Loaded Reports</h3><div class="facet-actions report-actions" role="group" aria-label="Loaded report selection"><button type="button" data-report-all aria-label="Select all loaded reports">All</button><button type="button" data-report-none aria-label="Select no loaded reports">None</button></div></div><div id="filesList"></div></section><section class="filter"><div class="filter-heading"><h3>Priority</h3><div class="facet-actions priority-actions" role="group" aria-label="Priority selection"><button type="button" data-facet-all="prio" aria-label="Select all priorities">All</button><button type="button" data-facet-none="prio" aria-label="Select no priorities">None</button></div></div><div id="priorityFilter"></div></section><section class="filter"><h3>Discipline-A</h3><div id="disciplineA"></div><label>Pair logic <select id="logic"><option>AND</option><option>OR</option></select></label></section><section class="filter"><h3>Discipline-B</h3><div id="disciplineB"></div></section><section class="filter"><h3>Clash Status</h3><div id="statusFilter"></div></section></aside>
<main class="main"><header class="hero"><h1 id="project"></h1><textarea id="remarks" class="remarks-input" maxlength="500" aria-label="Report remarks or contact notes" placeholder="Add contact details or report notes…"></textarea></header><div id="dashboardAlert" class="error-banner" role="alert" hidden></div><section class="cards" id="cards"></section><section class="panel trend-panel"><div class="toolbar"><div><h2 style="margin:0">Weekly Clash Analytics</h2><span class="sub">Weekly snapshots. Latest loaded report per project in each week.</span></div><span class="pill" id="trendMeta">0 weeks</span></div><div class="trend-visuals"><section class="analytics-chart-panel"><div><h3>Weekly Status Trend</h3><span class="sub">Latest snapshot per week</span></div><div id="trendChart" class="analytics-chart-scroll" role="group" aria-label="Weekly line chart of clash status counts"></div><div id="weeklyTrendLegend" class="chart-legend"></div></section><section class="analytics-chart-panel"><div><h3>Weekly Status</h3><span class="sub">Stacked clash counts by week</span></div><div id="weeklyStackedChart" class="analytics-chart-scroll" role="group" aria-label="Weekly stacked column chart of clash status counts"></div><div id="weeklyStackedLegend" class="chart-legend"></div></section><section class="completion-pie-panel" aria-labelledby="completionPieTitle"><div><h3 id="completionPieTitle">This Week</h3><span class="sub">Current status breakdown</span></div><div id="completionPie" aria-live="polite"></div><div id="completionPieLegend" class="completion-pie-legend"></div></section></div><div class="timeline-controls"><button id="playTimeline" type="button">▶ Play weekly history</button><label for="timelineSlider">Week snapshot</label><input id="timelineSlider" type="range" min="0" max="0" value="0" disabled><span id="timelineLabel" aria-live="polite"></span><button id="clearSelections" type="button">Reset Filters</button></div></section><section class="analytics-lower"><section class="panel heatmap-panel"><div class="toolbar"><div><h2 style="margin:0">Clash Intensity by Discipline</h2><span class="sub">Filtered clash counts. Higher counts use stronger magenta.</span></div></div><div id="disciplineHeatmap" class="heatmap-wrap"></div></section><section class="panel wow-panel"><div class="toolbar"><div><h2 style="margin:0">Week-over-Week</h2><span class="sub">Selected week vs previous available weekly snapshot.</span></div></div><div id="weekOverWeek"></div></section></section><section class="panel"><div class="toolbar"><div><h2 style="margin:0">Clash status flow</h2><span class="sub">Click a stage to filter the register.</span></div><span class="pill" id="filteredCount"></span></div><div class="flow" id="flow"></div></section><section class="panel"><div class="toolbar"><div><h2 style="margin:0">Overall Clash Report / Discipline</h2><span class="sub">Click a clash test name to filter by test, or select a row to filter by discipline pair.</span></div><details class="test-picker"><summary id="testPickerSummary">Clash tests · All</summary><div class="test-picker-menu"><div class="facet-actions"><button type="button" data-test-all>Select All</button><button type="button" data-test-none>Select None</button></div><div id="testFilterList" class="test-filter-list"></div></div></details><button class="no-print" onclick="downloadCsv()">⇧ CSV</button></div><div class="table-wrap"><table class="pair-table"><thead><tr><th>Clash Tests</th><th>Discipline A</th><th>Discipline B</th><th>Tests</th><th>Total</th><th>New + Active</th><th>Reviewed</th><th>Approved</th><th>Resolved</th></tr></thead><tbody id="pairs"></tbody></table></div></section><section class="panel"><div class="toolbar"><div><h2 style="margin:0">Clash Register</h2><section class="panel"><div class="toolbar"><div><h2 style="margin:0">Clash Register</h2><span class="sub">Review statuses, assignment and locations. Priority and reassignment edits are local to this dashboard.</span></div><div class="bulk-assignment"><label for="bulkAssignee">Bulk Assign</label><input id="bulkAssignee" type="text" maxlength="120" placeholder="Member name"><button id="bulkAssignApply" type="button">Assign selected</button><button id="bulkSelectPage" type="button">Select page</button><button id="bulkSelectFiltered" type="button">Select filtered</button><button id="bulkClearSelection" type="button">Clear selection</button><span id="bulkSelectionCount" class="sub">0 selected</span><span id="bulkStatus" class="sub" role="status"></span></div><small class="sub bulk-note">Assignments are saved in this browser only; they do not update the NWF/NWD.</small><input id="search" placeholder="Search clashes, tests, items…"></div><div class="toolbar register-pager"><span id="registerPageInfo" class="sub"></span><div><button id="registerPrev" type="button" onclick="changeRegisterPage(-1)">Previous</button> <button id="registerNext" type="button" onclick="changeRegisterPage(1)">Next</button></div></div><div class="table-wrap"><table><thead><tr><th>Select</th><th>Status</th><th>Priority</th><th>Test / clash</th><th>Discipline pair</th><th>Items / models</th><th>Distance</th><th>Coordinates (__UNITS__)</th><th>Clash Tolerance</th><th>Assigned to</th><th>Approved by</th><th>Created / approved</th><th>Viewpoint / image</th></tr></thead><tbody id="results"></tbody></table></div><p class="notes">Navisworks saves result status, assignment, approval metadata, geometry, and viewpoint availability. Priority is inferred from the first character of the Clash Test name before '_'; manual priority edits are local review notes. The API does not expose viewpoint titles, so viewpoint is shown as saved/none. Browser edits do not write back to NWF/NWD. Save the model in Navisworks to retain native status changes.</p></section></main></div>
<script type="application/json" id="reportData">__DATA__</script><script>
const original=JSON.parse(document.getElementById('reportData').textContent);let reports=[original],pairLock=null;let statuses=[];let priorities=[];let filterState={report:null,prio:null,da:null,db:null,stat:null,test:null};const reportRowCache=new WeakMap();let registerPage=0,refreshQueued=false,refreshFacetsQueued=false;let selectedClashKeys=new Set(),visibleClashes=[];const registerPageSize=100;const dashboardDebug=new URLSearchParams(location.search).get('navproDebug')==='1';function esc(x){return String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function parseTestName(name){name=String(name||'');const first=name.indexOf('_'),sep=first<0?-1:name.toUpperCase().indexOf('_VS_',first+1),last=name.toUpperCase().lastIndexOf('_VS_');if(first<=0||sep<=first+1||sep!==last||sep+4>=name.length)return{IsValid:false,Priority:'',DisciplineA:'',DisciplineB:'',ValidationMessage:'Invalid clash test name. Expected Priority_DisciplineA_VS_DisciplineB, for example H_CI-Irrigation_VS_CS-Storm.'};const p=name.slice(0,first),a=name.slice(first+1,sep),b=name.slice(sep+4);if(!p.trim()||p!==p.trim()||!a.trim()||a!==a.trim()||!b.trim()||b!==b.trim()||[p,a,b].some(x=>x.toUpperCase()==='VS'))return{IsValid:false,Priority:'',DisciplineA:'',DisciplineB:'',ValidationMessage:'Invalid clash test name. Expected Priority_DisciplineA_VS_DisciplineB, for example H_CI-Irrigation_VS_CS-Storm.'};return{IsValid:true,Priority:p,DisciplineA:a,DisciplineB:b,ValidationMessage:'Valid naming convention.'}}function allResults(){return reports.flatMap(r=>r.Results||[]).map(x=>{const p=parseTestName(x.TestName);x.Priority=p.IsValid?p.Priority:'';x.DisciplineA=p.IsValid?p.DisciplineA:'Unclassified';x.DisciplineB=p.IsValid?p.DisciplineB:'Unclassified';x.NameValidation=p.ValidationMessage;x.IsNameValid=p.IsValid;return x})}function key(r){return r.ReportId+':'+r.Id}function saved(k,d){try{return localStorage.getItem('navpro:'+k)||d}catch(e){return d}}function put