function priorityFacetValues(sourceReports){const rows=filteredRows(sourceReports,'prio',true,true),values=new Set(rows.map(priority));if(filterState.stat!==null)return[...values];const query=search.value.trim().toLowerCase(),logic=document.getElementById('logic').value,resultKeys=new Set();sourceReports.forEach(r=>reportRows(r).forEach(x=>{if(!x.Unmapped&&Number(x.Count||0)>0)resultKeys.add(r.ReportId+'|'+x.TestName)}));sourceReports.forEach(r=>(r.Tests||[]).forEach(t=>{if(resultKeys.has(r.ReportId+'|'+t.Name))return;const p=parseTestName(t.Name),a=p.IsValid?p.DisciplineA:'Unclassified',b=p.IsValid?p.DisciplineB:'Unclassified',aok=stateAllows('da',a),bok=stateAllows('db',b);if(!(logic==='AND'?aok&&bok:aok||bok))return;if(pairLock&&pairLock!==a+'|'+b)return;if(query&&!t.Name.toLowerCase().includes(query))return;values.add(p.IsValid?p.Priority:'Unassigned')}));return[...values]}
