function renderFacet(cls,container,values){values=[...new Set(values)].sort((a,b)=>String(a).localeCompare(String(b),undefined,{numeric:true,sensitivity:'base'}));const old=filterState[cls];if(old!==null){const kept=new Set(values.filter(v=>old.has(v)));filterState[cls]=!values.length||kept.size===values.length?null:kept}const active=filterState[cls],actions=(cls==='da'||cls==='db')?'<div class="facet-actions"><button type="button" data-facet-all="'+cls+'">Select All</button><button type="button" data-facet-none="'+cls+'">Select None</button></div>':'';const list=values.map(value=>'<label><input type="checkbox" class="'+cls+'" value="'+esc(value)+'"'+(active===null||active.has(value)?' checked':'')+'>'+esc(value)+'</label>').join('')||'<div class="sub">No matching values</div>';container.innerHTML=actions+list}
