function reportRows(report){const cached=reportRowCache.get(report);if(cached)return cached;const results=report.Results||[];if(results.length){const detailed=results.map(x=>{const p=parseTestName(x.TestName);return Object.assign({},x,{ReportId:report.ReportId,Priority:p.IsValid?p.Priority:'Unassigned',DisciplineA:p.IsValid?p.DisciplineA:'Unclassified',DisciplineB:p.IsValid?p.DisciplineB:'Unclassified',NameValidation:p.ValidationMessage,IsNameValid:p.IsValid,Summary:false,Unmapped:false,Count:1})});reportRowCache.set(report,detailed);return detailed}const rows=[];(report.Tests||[]).forEach(t=>{const p=parseTestName(t.Name),counts=t.ClashStatusCounts||{};Object.keys(counts).forEach(status=>{const count=Number(counts[status]||0);if(count>0)rows.push({ReportId:report.ReportId,Id:'summary:'+t.Name+':'+status,TestName:t.Name,TestTolerance:t.Tolerance,DisplayUnits:report.DisplayUnits,Status:status,Priority:p.IsValid?p.Priority:'Unassigned',DisciplineA:p.IsValid?p.DisciplineA:'Unclassified',DisciplineB:p.IsValid?p.DisciplineB:'Unclassified',Count:count,Summary:true,Unmapped:false})})});if(!rows.length){const all=report.AllStatusCounts||{};Object.keys(all).forEach(status=>{const count=Number(all[status]||0);if(count>0)rows.push({ReportId:report.ReportId,Id:'aggregate:'+status,TestName:'All test summaries',Status:status,Priority:'Unassigned',DisciplineA:'Unclassified',DisciplineB:'Unclassified',Count:count,Summary:true,Unmapped:true})})}reportRowCache.set(report,rows);return rows}
async function restoreReportsFolder(){try{if(!window.showDirectoryPicker||!window.indexedDB)return;const db=await openFolderDb(),handle=await new Promise((resolve,reject)=>{const req=db.transaction('preferences').objectStore('preferences').get('reportsFolder');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});db.close();if(!handle)return;reportFolderHandle=handle;if(await handle.queryPermission({mode:'read'})==='granted'){folderStatus.textContent='Restoring report folder '+handle.name+'…';await scanReportFolder();reportFolderTimer=setInterval(scanReportFolder,15000)}else folderStatus.textContent='Saved reports folder '+handle.name+' is ready. Select the folder to grant access and resume automatic refresh.'}catch(e){}}
